const test = require('node:test');
const assert = require('node:assert/strict');
const { sum } = require('../src/sum.js');

const cases = [
  { name: 'adds positive integers', a: 2, b: 3, expected: 5 },
  { name: 'adds negative numbers', a: -2, b: -3, expected: -5 },
  { name: 'adds numbers with different signs', a: -2, b: 5, expected: 3 },
  { name: 'adds zero', a: 0, b: 7, expected: 7 },
  { name: 'adds two zeros', a: 0, b: 0, expected: 0 },
  { name: 'adds fractional numbers', a: 1.5, b: 2.25, expected: 3.75 }
];

for (const { name, a, b, expected } of cases) {
  test(name, () => {
    assert.equal(sum(a, b), expected);
  });
}
